@Override // android.view.View
public boolean onTouchEvent(@Nullable MotionEvent event) {
    if (isEnabled() || !this.allowClickWhenDisabled) {
        return super.onTouchEvent(event);
    }
    if (event != null && event.getAction() == 1) {
        performClick();
    }
    return true;
}
